// MENU SYSTEM  -- pause overlay bound to tables: status / inventory / save.
// Opened by action {action:"openMenu"} or the M key.
// ---------------------------------------------------------------------------
var MENU = null, menuEl = null;
function openMenu() { MENU = { tab: "status" }; renderMenu(); }
function closeMenu() { MENU = null; if (menuEl) menuEl.style.display = "none"; }
function renderMenu() {
  if (!MENU) return;
  if (!menuEl) {
    menuEl = document.createElement("div");
    menuEl.style.cssText = "position:absolute;inset:8px;background:rgba(10,14,20,.96);" +
      "border:1px solid #3f5c6b;border-radius:8px;padding:12px;color:#e8e2d0;" +
      "font-size:13px;overflow:auto;pointer-events:auto";
    hud.appendChild(menuEl);
  }
  var pl = nodes[playerId] || {};
  var h = '<div style="display:flex;gap:6px;margin-bottom:10px">';
  ["status", "items", "save"].forEach(function (tab) {
    h += '<div data-tab="' + tab + '" style="padding:5px 12px;border-radius:4px;cursor:pointer;background:' +
      (MENU.tab === tab ? "#3f5c6b" : "#171d28") + '">' + tab + "</div>";
  });
  h += '<div data-x="1" style="margin-left:auto;padding:5px 12px;background:#8c4a42;border-radius:4px;cursor:pointer">close</div></div>';

  if (MENU.tab === "status") {
    h += "<div>HP " + (pl.hp || 0) + "/" + (pl.maxHp || 0) + "</div>";
    h += "<div>Level " + playerLevel() + " &nbsp; XP " + (world.flags.xp || 0) + "</div>";
    h += "<div>Gold " + gold() + "</div>";
    h += "<div>ATK " + derivedStat((pl.stats && pl.stats.attack) || 0, "atk") +
      " &nbsp; DEF " + derivedStat(0, "def") + "</div>";
    var eq = Object.keys(INV.equipped).map(function (sl) { return __kvEsc(sl) + ": " + __kvEsc(itemDef(INV.equipped[sl]).name || INV.equipped[sl]); });
    if (eq.length) h += '<div style="margin-top:6px;color:#8a8a8a">' + eq.join(" · ") + "</div>";
  } else if (MENU.tab === "items") {
    var ids = Object.keys(INV.items);
    if (!ids.length) h += '<div style="color:#8a8a8a">Empty.</div>';
    ids.forEach(function (id) {
      var it = itemDef(id);
      h += '<div data-use="' + id + '" style="display:flex;justify-content:space-between;padding:6px 8px;' +
        'margin-top:4px;background:#1b2430;border-radius:4px;cursor:pointer">' +
        "<span>" + __kvEsc(it.name || id) + " x" + invCount(id) + "</span>" +
        '<span style="color:#8a8a8a;font-size:11px">' + (it.kind === "weapon" || it.kind === "trinket" ? "equip" : (it.heal ? "use" : "")) + "</span></div>";
    });
  } else if (MENU.tab === "save") {
    h += '<div data-save="1" style="padding:8px 12px;background:#3f6b5c;border-radius:4px;cursor:pointer;display:inline-block">Save progress</div>';
    if (MENU.saved) h += '<div style="margin-top:6px;color:#49c07a">Saved.</div>';
  }
  menuEl.innerHTML = h;
  menuEl.style.display = "block";
  menuEl.onclick = function (e) {
    var t = e.target.closest ? e.target.closest("[data-tab],[data-x],[data-use],[data-save]") : e.target;
    if (!t || !t.getAttribute) return;
    if (t.getAttribute("data-x")) return closeMenu();
    var tab = t.getAttribute("data-tab");
    if (tab) { MENU.tab = tab; MENU.saved = false; return renderMenu(); }
    var use = t.getAttribute("data-use");
    if (use) {
      var it = itemDef(use);
      var pl2 = nodes[playerId];
      if (it.kind === "weapon" || it.kind === "trinket") equip(it.kind === "weapon" ? "weapon" : "trinket", use);
      else if (it.heal && pl2) { invRemove(use, 1); pl2.hp = Math.min(pl2.maxHp || 999, (pl2.hp || 0) + it.heal); }
      return renderMenu();
    }
    if (t.getAttribute("data-save")) { bridgeCommit(); MENU.saved = true; return renderMenu(); }
  };
}

