  if (ox <= 0) return null;
  var dy = pb[1] - pa[1], oy = (a.half[1] + b.half[1]) - Math.abs(dy);
  if (oy <= 0) return null;
  var dz = pb[2] - pa[2], oz = (a.half[2] + b.half[2]) - Math.abs(dz);
