    var cx = Math.max(bp[0] - hx, Math.min(sp[0], bp[0] + hx));
    var cy = Math.max(bp[1] - hy, Math.min(sp[1], bp[1] + hy));
    var cz = Math.max(bp[2] - hz, Math.min(sp[2], bp[2] + hz));
