function bakeLighting() {
  var cfg = scene.lighting;
  BAKE.done = false;
  if (!cfg) return;
  BAKE.ambient = hexRGB(cfg.ambient || "#404850");
  BAKE.occluders = collectOccluders();
  var rng = srandFor("bake:" + ((scene.meta || {}).seed || "s"));
  var budget = cfg.bakeBudgetMs || 120;
  var t0 = (typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now();
  var ids = Object.keys(nodes), baked = 0, skipped = 0;
  for (var k = 0; k < ids.length; k++) {
    var n = nodes[ids[k]];
    var g = n._geo;
    if (!g || !g.verts || !g.verts.length) continue;
    if (n._bake) continue;
    if (n.type === "Actor" && cfg.bakeActors !== true) continue;
    var now = (typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now();
    if (now - t0 > budget) { skipped++; continue; }
    var m = n._world || matIdent();
    // averaged vertex normals
    var vn = [], i;
    for (i = 0; i < g.verts.length; i++) vn.push({ x: 0, y: 0, z: 0 });
    for (i = 0; i < g.faces.length; i++) {
      var f = g.faces[i];
      var a = g.verts[f.i[0]], b2 = g.verts[f.i[1]], c2 = g.verts[f.i[2]];
      var fn = vnorm(vcross(vsub(b2, a), vsub(c2, a)));
      for (var q = 0; q < 3; q++) {
        vn[f.i[q]].x += fn.x; vn[f.i[q]].y += fn.y; vn[f.i[q]].z += fn.z;
      }
    }
    var out = [];
    for (i = 0; i < g.verts.length; i++) {
      var wp = matApply(m, g.verts[i]);
      var nn = vnorm(vn[i]);
      if (!isFinite(nn.x) || (!nn.x && !nn.y && !nn.z)) nn = { x: 0, y: 1, z: 0 };
      out.push(bakePoint(wp.x, wp.y, wp.z, nn.x, nn.y, nn.z, cfg, n.id, rng));
    }
    n._bake = out;
    baked++;
  }
  BAKE.done = true;
  if (skipped) console.warn("bake budget hit: " + skipped + " meshes left unlit");
}

// Face shade from the baked vertices: average of the three corners. Returns
// null when the mesh has no bake, so the caller falls back to lambert.
function bakedFaceShade(n, face) {
  var bk = n._bake;
  if (!bk) return null;
  var a = bk[face.i[0]], b = bk[face.i[1]], c = bk[face.i[2]];
  if (!a || !b || !c) return null;
  return { r: (a.r + b.r + c.r) / 3, g: (a.g + b.g + c.g) / 3, b: (a.b + b.b + c.b) / 3 };
}
// Tints a base colour by baked irradiance, clamped to display range.
function bakedColor(col, irr) {
  var c = hexRGB(col);
  var r = Math.min(255, Math.round(c.r * irr.r * 255));
  var g = Math.min(255, Math.round(c.g * irr.g * 255));
  var b = Math.min(255, Math.round(c.b * irr.b * 255));
  return "rgb(" + r + "," + g + "," + b + ")";
}

var LIGHT = vnorm(v3(-0.4, 0.8, -0.3));

